import test from'node:test';import assert from'node:assert/strict';import{inspectOtherControllerRun}from'./other-controller-run.mjs';import{REPOSITORY,REPOSITORY_ID,WORKFLOW_ID,WORKFLOW_PATH}from'./release-policy.mjs';
const controller='a'.repeat(40),candidate=controller;const fixture=()=>{const run={id:123,repository:{id:REPOSITORY_ID,full_name:REPOSITORY},head_repository:{id:REPOSITORY_ID},workflow_id:WORKFLOW_ID,path:WORKFLOW_PATH,head_branch:'alpha',head_sha:controller,event:'workflow_dispatch',status:'completed',conclusion:'failure',run_attempt:1,created_at:'2026-10-27T00:00:00Z',updated_at:'2026-10-27T00:02:00Z'};const artifact={id:456,name:'gate-plan',expired:false,size_in_bytes:123,digest:'sha256:'+'d'.repeat(64),created_at:'2026-10-27T00:01:00Z',workflow_run:{id:123,repository_id:REPOSITORY_ID,head_repository_id:REPOSITORY_ID,head_sha:controller,head_branch:'alpha'}};const jobs=['resolve','plan'].map(name=>({name,run_id:123,run_attempt:1,head_sha:controller,head_branch:'alpha',status:'completed',conclusion:'success',started_at:'2026-10-27T00:00:00Z',completed_at:'2026-10-27T00:01:30Z'}));const archivedPlan={sha:'b'.repeat(40),controller,fingerprint:'c'.repeat(64)};return{snapshot:{run,jobs,artifacts:[artifact]},artifact,archivedPlan,reconstructedPlan:structuredClone(archivedPlan),candidate,controller};};
test('failed unrelated candidate is scoped without accepting coverage',()=>{const p=inspectOtherControllerRun(fixture());assert.equal(p.coverageReused,false);assert.equal(p.releaseAuthorized,false);});
for(const[name,mutate]of Object.entries({sameCandidate:x=>{x.archivedPlan.sha=candidate;x.reconstructedPlan.sha=candidate},foreignRepository:x=>x.snapshot.run.repository.id=2,foreignController:x=>x.snapshot.run.head_sha='f'.repeat(40),mainBranch:x=>x.snapshot.run.head_branch='main',pushEvent:x=>x.snapshot.run.event='push',running:x=>x.snapshot.run.status='in_progress',cancelled:x=>x.snapshot.run.conclusion='cancelled',rerun:x=>x.snapshot.run.run_attempt=2,planMismatch:x=>x.reconstructedPlan.fingerprint='different',duplicatePlan:x=>x.snapshot.artifacts.push(x.artifact),expiredPlan:x=>x.artifact.expired=true,oversizedPlan:x=>x.artifact.size_in_bytes=1048577,foreignArtifact:x=>x.artifact.workflow_run.id=456,failedResolver:x=>x.snapshot.jobs[0].conclusion='failure',missingPlanJob:x=>x.snapshot.jobs.pop(),duplicateJob:x=>x.snapshot.jobs.push(x.snapshot.jobs[1]),foreignJob:x=>x.snapshot.jobs[1].head_sha='f'.repeat(40),badChronology:x=>x.artifact.created_at='2026-10-27T00:03:00Z'}))test('refuses '+name,()=>{const x=fixture();mutate(x);assert.throws(()=>inspectOtherControllerRun(x));});
